        code = CASE WHEN p_data ? 'code' THEN NULLIF(p_data->>'code', '') ELSE code END,
        name = CASE WHEN p_data ? 'name' THEN NULLIF(p_data->>'name', '') ELSE name END,
        description = CASE WHEN p_data ? 'description' THEN NULLIF(p_data->>'description', '') ELSE description END,
        icon = CASE WHEN p_data ? 'icon' THEN NULLIF(p_data->>'icon', '') ELSE icon END,
        sort_order = CASE WHEN p_data ? 'sortOrder' THEN COALESCE(NULLIF(p_data->>'sortOrder', '')::int, 0) ELSE sort_order END,
